# November 18, 2026: White Mountains & North Country, New Hampshire (region nhw, drawn at random by tools/choose.py).
# Southern and western Grafton County, which had nothing on the map: the Pemigewasset valley (Ashland, Holderness,
# Plymouth, Campton), the Mascoma valley (Canaan, Enfield, Lebanon, Hanover), Dorchester and the Connecticut River
# towns (Lyme, Orford, Piermont), plus the drowned-out old village of Hill just over the line in Merrimack County.
# Facts come from the linked sources, opened in this session: Wikipedia read as raw text (wiki_raw.py), the state's
# 2015 Livermore Falls cultural landscape report, a Register nomination, NH State Parks, the Enfield Shaker Museum,
# HMdb and newspaper pages through page.py. Hours that could not be read say so.
from data_b import N
from data_ma import W
